"""Family, power and relationship cases (basic mode). Simplified decision analyses of common situations.
They show how the choices change outcomes, using healthy, respectful approaches. They are not
guidance for a crisis: anyone in danger should contact local emergency services or a support line.
"""

from build_core import B, C, O, R, S

SIMS = [
    S("setting-limits-with-a-teenager", "Setting Screen-Time Limits With a Teenager",
      ["Life games", "Society and groups", "Negotiation and fairness"],
      "A teenager spends many hours online and resists any limit. Limits that are agreed together, explained clearly and reviewed are followed more often than rules imposed without discussion. The choices are how you start the conversation, what rule you set, and how you review it.",
      [R("Round 1. The limit is needed. How do you start?",
         O("Talk it through and agree a rule together", 2, "Agreed rules are followed more often than rules imposed without discussion.",
           C("The teenager:", B(0.6, "Agrees to a fair rule", 2, "Having a say makes the rule feel fair."),
             B(0.4, "Pushes back", 0, "Some pushback is normal; the talk still helps."))),
         O("Set a strict rule with no discussion", -1, "Imposed rules are often broken or hidden.",
           C("The teenager:", B(0.4, "Complies openly", 1, "Compliance is possible but resentful."),
             B(0.6, "Hides the use", -2, "Hidden use makes problems harder to see."))),
         O("Do nothing for now", -1, "Without a rule, habits and problems grow unchecked.")),
       R("Round 2. Two weeks later. How do you review the rule?",
         O("Review it together and adjust if it is not working", 2, "Regular review keeps the rule fair and effective."),
         O("Punish any slip immediately", -1, "Harsh punishment can drive the behaviour out of sight."),
         O("Drop the rule because it is hard to keep", -1, "Dropping a rule without review teaches that limits are optional.")),
       ],
      4, 2, ("The rule was agreed, followed and kept fair.", "The rule was partly followed and reviewed.", "The rule was imposed, hidden or dropped.")),

    S("supporting-without-enabling", "Supporting Someone Without Enabling Them",
      ["Life games", "Society and groups"],
      "A family member keeps asking you for money to cover the consequences of a problem they have not yet faced. Helping in ways that build their independence is different from covering costs that keep the problem going. The choices are how much to give, on what conditions, and where to point them for support.",
      [R("Round 1. The request comes again. What do you offer?",
         O("Offer help that builds independence, such as a plan and a support service", 2, "Practical help with a plan supports recovery without covering the problem's costs.",
           C("The family member:", B(0.5, "Accepts the plan", 2, "A concrete plan gives them a way forward."),
             B(0.5, "Declines the plan", 0, "You can keep the offer open without paying the cost."))),
         O("Pay the bill again without conditions", -2, "Unconditional payment usually removes the reason to change.",
           C("The family member:", B(0.7, "Keeps the same pattern", -2, "Nothing has changed, so the problem continues."),
             B(0.3, "Gets help anyway", 0, "Sometimes relief helps, but the pattern is rarely fixed by money alone."))),
         O("Refuse all contact until they change", -1, "Cutting off contact removes a source of support you may still need to give.")),
       R("Round 2. Things get worse. What is your response?",
         O("Keep your boundaries and share the support options again", 2, "Clear, consistent boundaries and an open offer of support work best together."),
         O("Give in when they are upset", -2, "Giving in after an upset teaches that upset works."),
         O("Step back and look after your own wellbeing", 1, "Looking after yourself lets you keep supporting over the long term.")),
       ],
      4, 2, ("Support built independence and boundaries held.", "Support continued with some boundaries.", "Payments continued and the problem grew.")),

    S("sibling-inheritance-dispute", "Dividing an Inheritance Between Siblings",
      ["Negotiation and fairness", "Life games", "Society and groups"],
      "Three siblings must divide a family home and savings. They disagree about what is fair, and about the care one of them gave to a parent. A fair process, written down and agreed in advance, usually ends a dispute better than a fight over each item.",
      [R("Round 1. The disagreement starts. What process do you propose?",
         O("Agree a written process, with an independent valuation", 2, "Written steps and an independent valuation reduce suspicion about the numbers.",
           C("Siblings:", B(0.6, "Accept the process", 2, "A clear process makes the outcome easier to accept."),
             B(0.4, "Want changes", 0, "Changes are normal; the process can still be agreed."))),
         O("Divide items by who asks first", -1, "First-come division rewards speed and pressure over fairness.",
           C("Siblings:", B(0.5, "Accept it", 0, "Some accept, but the quiet ones lose out."),
             B(0.5, "Argue over each item", -2, "Item-by-item fights cost relationships and money."))),
         O("Refuse to discuss until the others apologise", -2, "Refusing to talk leaves the estate in limbo and makes the dispute harder to resolve.")),
       R("Round 2. Care given to a parent is raised. How do you handle it?",
         O("Recognise the care in the process, such as a fair payment for it", 2, "Acknowledging care in money or agreed terms addresses the grievance directly."),
         O("Dismiss the care as not mattering", -2, "Dismissing it deepens the grievance."),
         O("Ask a mediator to help the family talk", 2, "A mediator can make a fair conversation possible.")),
       ],
      4, 2, ("The estate was divided fairly and the family kept talking.", "The division was agreed with some resentment.", "The dispute went to a long fight that cost the family.")),

    S("power-dynamics-manager", "Working With a Domineering Manager",
      ["Work games", "Society and groups", "Government and politics"],
      "A manager makes decisions alone, takes credit for team work, and dismisses questions. The choices are how to raise concerns, whether to document the issues, and when to involve others. Clear, factual and documented concerns protect you more than confrontation in the moment.",
      [R("Round 1. A decision is taken without you. How do you respond?",
         O("Raise it privately, factually and specifically", 2, "A calm, specific conversation gives the manager a chance to respond.",
           C("The manager:", B(0.5, "Listens and changes", 2, "Specific feedback is easier to act on."),
             B(0.5, "Dismisses it", -1, "Dismissal is a signal to document and escalate."))),
         O("Confront the manager in front of the team", -2, "Public confrontation invites defensiveness and can harm your position.",
           C("The manager:", B(0.2, "Responds well", 1, "Some respond calmly even in public."),
             B(0.8, "Retaliates", -3, "Public confrontation often leads to retaliation."))),
         O("Stay silent and hope it changes", -1, "Silence lets the pattern continue and can damage your work.")),
       R("Round 2. The pattern continues. What do you do?",
         O("Document the dates and facts and raise them with HR or a trusted senior leader", 2, "Documented facts protect you and create a fair route to resolution."),
         O("Post about it publicly", -2, "Public posts can breach policy and make the situation harder to resolve."),
         O("Look for a transfer or new role while you keep records", 1, "Options give you security while the issue is addressed.")),
       ],
      4, 2, ("The issue was resolved through a fair, documented process.", "The situation improved partly, with a move or a compromise.", "The pattern continued and the cost to you grew.")),

    S("ageing-parent-care-split", "Sharing Care for an Ageing Parent",
      ["Life games", "Negotiation and fairness", "Society and groups"],
      "Several adult children must share the care of a parent who needs more support. Care work is unequal: one sibling may give most of the time, while others give money or nothing. A fair split, agreed openly and reviewed as needs change, keeps the family working together.",
      [R("Round 1. The care needs grow. How do you propose to share it?",
         O("Agree a shared plan with time, money and tasks written down", 2, "A written plan makes contributions visible and fair.",
           C("Siblings:", B(0.6, "Agree to the plan", 2, "A clear plan reduces resentment."),
             B(0.4, "Want to adjust it", 0, "Adjusting the plan is normal; the framework still helps."))),
         O("Let the sibling who lives nearest do most of the work", -1, "Unequal care leads to burnout and resentment.",
           C("Nearby sibling:", B(0.4, "Copes for now", 0, "Some carers cope for a while."),
             B(0.6, "Burns out", -2, "Burnout harms the carer and the parent."))),
         O("Hire paid care without discussing the costs", 0, "Paid care can help, but without agreement on costs it can create new disputes.")),
       R("Round 2. One sibling asks for a break. How do you respond?",
         O("Arrange respite and review the plan with everyone", 2, "Respite and a review keep the care sustainable."),
         O("Tell them to carry on", -2, "Refusing a break risks the carer and the care."),
         O("Ask the parent what they want", 2, "Including the parent respects their wishes and needs.")),
       ],
      4, 2, ("The care was shared fairly and sustained.", "The care was shared unevenly but managed.", "One carer burned out and the family split.")),

    S("young-child-school-refusal", "A Child Who Refuses to Go to School",
      ["Life games", "Society and groups"],
      "A young child is refusing to go to school, and is distressed each morning. The reason may be worry, bullying, or a difficulty the child cannot yet describe. Understanding the cause, working with the school, and keeping calm routines usually helps more than force or punishment.",
      [R("Round 1. The refusal starts. What is your first step?",
         O("Talk gently to find the cause and contact the school", 2, "Finding the cause and involving the school is the first step to a lasting fix.",
           C("The school:", B(0.7, "Shares what they have seen", 2, "Shared information makes a fix easier to find."),
             B(0.3, "Sees nothing wrong", 0, "The cause may still be found at home or in friendships."))),
         O("Force the child to go each morning", -2, "Forcing distress can make the refusal stronger and damages trust.",
           C("The child:", B(0.3, "Goes, but stays distressed", -1, "The distress continues."),
             B(0.7, "Refuses more strongly", -2, "Force tends to increase the refusal."))),
         O("Keep the child home without a plan", -1, "Staying home without a plan can make returning harder.")),
       R("Round 2. The cause is clearer. How do you help the child return?",
         O("Agree a gradual plan with the school and a calm morning routine", 2, "A gradual plan builds confidence and keeps the child connected to school."),
         O("Punish the refusal", -2, "Punishment adds fear to an already hard situation."),
         O("Seek support from the school counsellor or a child specialist", 2, "Specialist support helps when the cause is not obvious.")),
       ],
      4, 2, ("The child returned with a plan and the cause was addressed.", "The child attended more with support.", "The refusal continued and the child became more distressed.")),
]
